function UIActionPointMapNode:Refresh(id, index)
    self._data = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not self._data then
        return
    end
    self._ind = checkNumber(index)
    self:FillSelf()
end

function UIActionPointMapNode:RefreshCommonBattle(id, index)
    self._data = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not self._data then
        return
    end
    self._ind = checkNumber(index)

    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockQuest(self._data.id)
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._data.id)

    CfUtils.SetActive(self.LockGroup, not isUnlock)
    CfUtils.SetActive(self.Cell_Root.transform:Find("FinishGroup"), isPass)

    CfUtils.SetActive(self.ImgTask, false)
    CfUtils.SetActive(self.ImgFrame, false)
    CfUtils.SetActive(self.TypeGroup, false)

    CfUtils.SetUISwitchImage(self.ImgNormal, (checkNumber(self._data.levelType) == 1) and 2 or 1)
    local go = self.Cell_Root.transform:Find("MainGroup/MainGroupRoot/ImgText")
    CfUtils.SetActive(go, true)
    CfUtils.SetUISwitchText(go, (checkNumber(self._data.levelType) == 1) and 2 or 1)
    --CfUtils.SetCanvasGroupAlpha(self.Cell_Root, isUnlock and 1 or 0.5)

    local t = RewardConfMgr:GetInstance():GetQuestRewardData(self._data.id, Constants.QuestRewardType.RegularReward)
    --if table.count(t) <= 0 then
    --    t = RewardConfMgr:GetInstance():GetQuestRewardData(self._data.id, Constants.QuestRewardType.SilverBox)
    --    if table.count(t) <= 0 then
    --        t = RewardConfMgr:GetInstance():GetQuestRewardData(self._data.id, Constants.QuestRewardType.CopperBox)
    --    end
    --end
    if table.count(t) > 0 then
        local goodsData = t[1]
        CfUtils.RefeshGoodGo2(self.Cell_Root.transform:Find("MainGroup/MainGroupRoot/GoodNode"), goodsData.goodsId, string.format('x%d', checkNumber(goodsData.num)), nil, nil, function()
            
        end)
    end

    CfUtils.FillText(self.TxtDesc, self._data.name)
    CfUtils.FillText(self.TxtNumber, self._data.label)
    --CfUtils.FillText(self.TxtType1, ActionUtils.GetQuestTypeName(self._data.levelType))
    CfUtils.FillText(self.TxtType2, ActionUtils.GetQuestTypeName(self._data.levelType))
    CfUtils.SetUISwitchImage(self.ImgType2, self._data.levelType)
    CfUtils.SetUISwitchText(self.TxtDesc, isUnlock and 1 or 3)
    CfUtils.SetUISwitchText(self.TxtNumber, isUnlock and 1 or 3)

    self._co = CfUtils.PlayDelayShowAnimate(self.controller.gameObject.transform:Find("Cell_Root"), self._ind, 0.05, 0, "ActionPointMapDialog_Normal_Cell_DropDown")
end

function UIActionPointMapNode:FillSelf()
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockQuest(self._data.id)
    --if not isUnlock then
    --    CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Locked")
    --else
    --    CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Normal")
    --end
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._data.id)

    CfUtils.SetActive(self.LockGroup, not isUnlock)
    CfUtils.SetActive(self.Cell_Root.transform:Find("FinishGroup"), isPass)

    --CfUtils.SetActive(self.Cell_Root.transform:Find("MainGroup/ImgBg"), isUnlock)
    --CfUtils.SetActive(self.Cell_Root.transform:Find("MainGroup/ImgText"), isUnlock)
    --CfUtils.SetActive(self.CommonTypeGroup, isUnlock)

    CfUtils.SetActive(self.ImgTask, false)
    CfUtils.SetActive(self.ImgFrame, false)
    CfUtils.SetActive(self.TypeGroup, false)

    CfUtils.FillImage(self.ImgNormal, ActionUtils.GetQuestTypeIcon(self._data.levelType, isUnlock))
    CfUtils.FillText(self.TxtDesc, self._data.name)
    CfUtils.FillText(self.TxtNumber, self._data.label)
    --CfUtils.FillText(self.TxtType1, ActionUtils.GetQuestTypeName(self._data.levelType))
    CfUtils.FillText(self.TxtType2, ActionUtils.GetQuestTypeName(self._data.levelType))
    CfUtils.SetUISwitchImage(self.ImgType2, self._data.levelType)
    CfUtils.SetUISwitchText(self.TxtDesc, isUnlock and 1 or 3)
    CfUtils.SetUISwitchText(self.TxtNumber, isUnlock and 1 or 3)

    self._co = CfUtils.PlayDelayShowAnimate(self.controller.gameObject.transform:Find("Cell_Root"), self._ind, 0.05, 0, "ActionPointMapDialog_Normal_Cell_DropDown")
end

function UIActionPointMapNode:FillSelect(isSelect)
    if self._selectCo ~= nil then
        cs_coroutine.stop(self._selectCo)
        self._selectCo = nil
    end
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockQuest(self._data.id)
    self._selectCo = cs_coroutine.start(function()
        if isSelect then
            if isUnlock then
                CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Selecting")
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Selected")
            else
                CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Locked_Selecting")
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Locked_Selected")
            end
        else
            if isUnlock then
                CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Normal")
            else
                CfUtils.PlayAnimation(self.controller.gameObject, "ActionPointMapDialog_Normal_Cell_Locked")
            end
        end
    end)
    if isSelect then
        CfUtils.SetUISwitchText(self.TxtDesc, 2)
        CfUtils.SetUISwitchText(self.TxtNumber, 2)
    else
        CfUtils.SetUISwitchText(self.TxtDesc, isUnlock and 1 or 3)
        CfUtils.SetUISwitchText(self.TxtNumber, isUnlock and 1 or 3)
    end
end 

function UIActionPointMapNode:OnDestroy()
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    if self._selectCo then 
        cs_coroutine.stop(self._selectCo)
        self._selectCo = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionPointMapNode